"""Shared post-state predicate for the synthetic fenced edge publication."""
COLS=['source_system','rel_type_id','id','source_type','source_id','target_type','target_id','schema_revision','entity_version','props_json','retained_json','order_key','source_feed','source_epoch','source_position','published_at','lookup_hash']
def post(batch):
 keep=[x for x in COLS if x not in ['props_json','entity_version','source_feed','source_epoch','source_position','published_at']]
 checks=[f's.{x} IS DISTINCT FROM e.{x}' for x in keep]+["e.props_json IS DISTINCT FROM s.new_props","e.entity_version IS DISTINCT FROM 7","e.source_feed IS DISTINCT FROM 'fixture-fused300k'","e.source_epoch IS DISTINCT FROM 'e'",f'e.source_position IS DISTINCT FROM {batch}',"e.published_at IS NULL","e.lookup_hash IS DISTINCT FROM sha2(to_json(named_struct('source_system',e.source_system,'rel_type_id',e.rel_type_id,'id',e.id)),256)"]
 checks += ["j.entity_kind IS DISTINCT FROM 'edge'","j.property_id IS DISTINCT FROM 201","j.entity_version IS DISTINCT FROM 7","j.operation IS DISTINCT FROM 'update'","j.old_present IS DISTINCT FROM true","j.new_present IS DISTINCT FROM true","j.schema_revision IS DISTINCT FROM s.schema_revision","j.event_ordinal IS DISTINCT FROM s.ordinal","j.source_epoch IS DISTINCT FROM 'e'","j.published_at IS NULL",f"j.source_time_text IS DISTINCT FROM 'synthetic-fused:{batch}'","from_json(concat('[',j.old_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.props_json,'$.201')","from_json(concat('[',j.new_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.new_props,'$.201')"]
 return ' OR '.join(checks)
